import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFileSync,realpathSync,lstatSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname,resolve,relative,sep} from 'node:path';
import {createHash} from 'node:crypto';
const project=resolve(process.argv[2] ?? fileURLToPath(new URL('../../',import.meta.url)));
const req=createRequire(resolve(project,'package.json'));
const cdkPath=req.resolve('aws-cdk-lib/package.json');
const cdkReq=createRequire(cdkPath);
const minimatchPath=cdkReq.resolve('minimatch/package.json');
const miniReq=createRequire(minimatchPath);
const braceEntry=miniReq.resolve('brace-expansion');
const braceRoot=resolve(dirname(braceEntry),'../..');
const bracePath=resolve(braceRoot,'package.json');
const realRoot=realpathSync(resolve(project,'node_modules'));
assert.equal(lstatSync(resolve(project,'node_modules')).isSymbolicLink(),false,'Use a physical npm ci dependency tree');
assert.ok(realRoot.startsWith(realpathSync(project)+sep),'Dependencies must belong to this project');
assert.ok(realpathSync(braceEntry).startsWith(realRoot+sep));
const cdk=JSON.parse(readFileSync(cdkPath));
const mini=JSON.parse(readFileSync(minimatchPath));
const brace=JSON.parse(readFileSync(bracePath));
assert.equal(cdk.version,'2.269.0');
assert.equal(mini.version,'10.2.5');
assert.equal(brace.version,'5.0.12');
const proof=JSON.parse(readFileSync(resolve(project,'vendor/aws-cdk-lib/provenance.json')));
const hashes=proof.contentChanges.map(change=>{
 const inside=change.path.replace('package/node_modules/brace-expansion/','');
 const hash=createHash('sha256').update(readFileSync(resolve(braceRoot,inside))).digest('hex');
 assert.equal(hash,change.afterSha256,inside);
 return {path:inside,sha256:hash};
});
const expand=miniReq('brace-expansion').expand;
assert.deepEqual(expand('file-{a,b}-{1..3}'),['file-a-1','file-a-2','file-a-3','file-b-1','file-b-2','file-b-3']);
assert.equal(cdkReq('minimatch').minimatch('file-b-2','file-{a,b}-{1..3}'),true);
console.log(JSON.stringify({timestamp:new Date().toISOString(),node:process.version,isolatedPhysicalDependencies:true,cdkVersion:cdk.version,minimatchVersion:mini.version,braceExpansionVersion:brace.version,braceEntry:relative(project,braceEntry).split(sep).join('/'),verifiedPatchedFiles:hashes,braceAndMinimatchSmoke:'passed'},null,2));
